bool DmBookmarks::validateJsonForUpdate(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, false))
            return false;
    }

    else
    {
        err = "The value of primary key must be set in the json object for update";
        return false;
    }

    if(pJson.isMember("tenant_id"))
    {
        if(!validJsonOfField(1, "tenant_id", pJson["tenant_id"], err, false))
            return false;
    }

    if(pJson.isMember("user_id"))
    {
        if(!validJsonOfField(2, "user_id", pJson["user_id"], err, false))
            return false;
    }

    if(pJson.isMember("document_id"))
    {
        if(!validJsonOfField(3, "document_id", pJson["document_id"], err, false))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(4, "created_at", pJson["created_at"], err, false))
            return false;
    }

    if(pJson.isMember("created_by_user_id"))
    {
        if(!validJsonOfField(5, "created_by_user_id", pJson["created_by_user_id"], err, false))
            return false;
    }

    if(pJson.isMember("last_modified_at"))
    {
        if(!validJsonOfField(6, "last_modified_at", pJson["last_modified_at"], err, false))
            return false;
    }

    if(pJson.isMember("last_modified_by_user_id"))
    {
        if(!validJsonOfField(7, "last_modified_by_user_id", pJson["last_modified_by_user_id"], err, false))
            return false;
    }

    if(pJson.isMember("is_deleted"))
    {
        if(!validJsonOfField(8, "is_deleted", pJson["is_deleted"], err, false))
            return false;
    }

    if(pJson.isMember("version"))
    {
        if(!validJsonOfField(9, "version", pJson["version"], err, false))
            return false;
    }

    return true;
}
